export const ID='HIDDEN_GEOJE_11',FOOT=[2756,180],SOLID=[2738,109,2793,130],BBOX=[2738,82,2793,129];
export function createChestState(){let opened=false;const marks=new Set;return{mark(id){if(id==='HIDDEN_GEOJE_11_MARK_A'||id==='HIDDEN_GEOJE_11_MARK_B')marks.add(id);return marks.size},reset(){marks.clear();opened=false},read(){return{opened,marks:[...marks],id:ID,rewardMutations:0,saveMutations:0}},interact({foot,facing,blocked=false}){if(blocked||!foot||Math.hypot(foot[0]-FOOT[0],foot[1]-FOOT[1])>24||facing!=='north')return{ok:false,reason:'approach'};if(marks.size<2)return{ok:false,reason:'two-marks'};if(opened)return{ok:false,reason:'already-open'};opened=true;return{ok:true,reason:'preview-only-open'}}}}
export function drawOpen(ctx,img,{camera=[0,0]}={}){ctx.save();ctx.translate(-camera[0],-camera[1]);ctx.beginPath();ctx.rect(2737,68,57,41);ctx.clip();ctx.drawImage(img,2701.24,40,137.7,120);ctx.restore()}
